    }
    assert a[..a.Length] == a[..];
    diff := maxVal - minVal;
}

// The order of the recursion in these two functions
// must match the order of the iteration in the algorithm above
function Min(a: seq<int>) : int
{
    if |a| == 1 then a[0]
